import os
from typing import Any, Dict, Optional

import requests


class ContentSafetyError(Exception):
    pass


def score_text_safety(text: str, categories: Optional[list[str]] = None) -> Dict[str, Any]:
    """
    Score user text for unsafe or policy-violating content using Perspective API.

    Returns a normalized dictionary with per-attribute scores and a simple risk summary.
    """
    api_key = os.getenv("PERSPECTIVE_API_KEY")
    if not api_key:
        raise ContentSafetyError("Missing required environment variable: PERSPECTIVE_API_KEY")

    if not isinstance(text, str) or not text.strip():
        raise ContentSafetyError("Input text must be a non-empty string.")

    if categories is None:
        categories = [
            "TOXICITY",
            "SEVERE_TOXICITY",
            "IDENTITY_ATTACK",
            "INSULT",
            "PROFANITY",
            "THREAT",
            "SEXUALLY_EXPLICIT",
            "FLIRTATION",
        ]

    url = "https://commentanalyzer.googleapis.com/v1alpha1/comments:analyze"
    payload = {
        "comment": {"text": text},
        "languages": ["en"],
        "requestedAttributes": {cat: {} for cat in categories},
        "doNotStore": True,
    }
    params = {"key": api_key}

    resp = requests.post(url, params=params, json=payload, timeout=20)
    if resp.status_code != 200:
        raise ContentSafetyError(
            f"Perspective API request failed: {resp.status_code} {resp.text}"
        )

    data = resp.json()
    attr_scores = {}
    attrs = data.get("attributeScores", {})

    for cat in categories:
        value = None
        summary = attrs.get(cat, {}).get("summaryScore", {})
        if isinstance(summary, dict):
            value = summary.get("value")
        attr_scores[cat.lower()] = value

    # Simple risk summary based on the maximum available score.
    numeric_scores = [v for v in attr_scores.values() if isinstance(v, (int, float))]
    max_score = max(numeric_scores) if numeric_scores else 0.0

    if max_score >= 0.90:
        risk_level = "high"
    elif max_score >= 0.60:
        risk_level = "medium"
    elif max_score >= 0.25:
        risk_level = "low"
    else:
        risk_level = "minimal"

    return {
        "provider": "Perspective API",
        "risk_level": risk_level,
        "max_score": max_score,
        "scores": attr_scores,
        "raw": data,
    }


def is_unsafe(text: str, threshold: float = 0.60) -> bool:
    """
    Convenience helper: returns True if any measured attribute score meets/exceeds threshold.
    """
    result = score_text_safety(text)
    return any(
        isinstance(v, (int, float)) and v >= threshold
        for v in result["scores"].values()
    )
